package main

const webUI = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Azeroth Diary Exporter</title><link rel="icon" type="image/png" href="/icon.png"><style>
:root{color-scheme:dark;--bg:#090d16;--panel:#111827;--panel2:#151f31;--line:#2b3852;--text:#eef3ff;--muted:#91a0bd;--gold:#d7ab59;--blue:#70a9ff;--green:#72d39b;--red:#ff7d88}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,#17243d 0,#090d16 38%,#06080e 100%);color:var(--text);font-family:Segoe UI,Inter,Arial,sans-serif;min-height:100vh}.wrap{max-width:900px;margin:auto;padding:34px 18px 60px}.hero{border:1px solid var(--line);border-radius:22px;padding:28px;background:linear-gradient(135deg,rgba(215,171,89,.10),rgba(112,169,255,.03)),rgba(17,24,39,.93)}.tag{color:var(--gold);font-weight:800;letter-spacing:.09em;font-size:.75rem}h1{margin:5px 0 6px;font-size:clamp(2rem,6vw,3.5rem);letter-spacing:-.045em}.muted{color:var(--muted);line-height:1.5}.version{float:right;color:var(--muted);font-size:.8rem}.panel{border:1px solid var(--line);border-radius:18px;background:rgba(17,24,39,.95);padding:20px;margin-top:16px}.panel h2{font-size:1rem;margin:0 0 14px;color:var(--gold)}label{display:block;font-size:.82rem;font-weight:700;margin:13px 0 6px}.row{display:grid;grid-template-columns:1fr auto;gap:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}input[type=text],select{width:100%;border:1px solid var(--line);border-radius:11px;background:#0b1120;color:var(--text);padding:12px 13px;font-size:.92rem;outline:none}input:focus,select:focus{border-color:var(--gold)}button{border:1px solid var(--line);border-radius:11px;background:var(--panel2);color:var(--text);padding:11px 14px;font-weight:700;cursor:pointer}button:hover{border-color:var(--gold);color:var(--gold)}button.primary{background:var(--gold);border-color:var(--gold);color:#111827;font-size:1rem;padding:13px 18px}button.danger:hover{border-color:var(--red);color:var(--red)}.checks{display:grid;gap:9px;margin-top:14px}.check{display:flex;gap:9px;align-items:flex-start;color:var(--muted);font-size:.9rem}.check input{margin-top:3px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.status{padding:14px;border-radius:12px;background:#0b1120;border:1px solid var(--line);margin-top:16px;min-height:52px}.status.ok{border-color:rgba(114,211,155,.6)}.status.err{border-color:rgba(255,125,136,.6)}.status b{display:block;margin-bottom:3px}.tiny{font-size:.78rem;color:var(--muted);margin-top:5px;word-break:break-all}.pill{display:inline-block;padding:4px 8px;border:1px solid var(--line);border-radius:999px;font-size:.72rem;color:var(--muted);margin-top:10px}.footer{text-align:center;color:#71809d;font-size:.8rem;margin-top:24px}@media(max-width:650px){.grid{grid-template-columns:1fr}.row{grid-template-columns:1fr}.actions button{flex:1}.version{float:none;display:block;margin-bottom:8px}}</style></head><body><main class="wrap"><section class="hero"><span id="version" class="version"></span><div class="tag">AZEROTH DIARY • OPTIONALER WINDOWS EXPORTER</div><h1>Azeroth Diary Exporter</h1><div class="muted">Liest ausschließlich die SavedVariables des Addons und erstellt daraus automatisch deine Browser-Chronik. Das Addon selbst bleibt unabhängig und der manuelle HTML-Export funktioniert weiterhin.</div><div class="pill">Keine Installation • Keine Änderungen an WoW-Daten</div></section>
<section class="panel"><h2>1. Azeroth Diary Daten</h2><label for="sourceList">Gefundene SavedVariables</label><select id="sourceList"></select><label for="source">Pfad zu AzerothDiary.lua</label><div class="row"><input id="source" type="text"><button onclick="pickSource()">Datei wählen</button></div><div class="tiny">WoW speichert neue Daten beim Logout, beim Beenden des Spiels oder nach /reload.</div><div class="actions"><button onclick="refreshSources()">Neu suchen</button></div></section>
<section class="panel"><h2>2. Export</h2><label for="output">Ziel-Datei</label><div class="row"><input id="output" type="text"><button onclick="pickOutput()">Ziel wählen</button></div><div class="grid"><div><label for="language">Sprache der HTML</label><select id="language"><option value="de">Deutsch</option><option value="en">English</option></select></div><div></div></div><div class="checks"><label class="check"><input id="wowhead" type="checkbox"><span>Wowhead-Links und Mouseover-Tooltips einbauen. Die Chronik selbst bleibt auch ohne Internet nutzbar.</span></label><label class="check"><input id="auto" type="checkbox"><span>Automatisch neu exportieren, wenn WoW die AzerothDiary.lua verändert (solange diese Exporter-Seite geöffnet ist).</span></label><label class="check"><input id="openAfter" type="checkbox"><span>HTML nach einem manuellen Export automatisch im Browser öffnen.</span></label></div><div class="actions"><button class="primary" onclick="runExport()">Jetzt exportieren</button><button onclick="openOutput()">HTML öffnen</button><button onclick="openFolder()">Ordner öffnen</button></div><div id="status" class="status"><b>Bereit</b><span>Wähle deine Datenquelle und exportiere die Chronik.</span></div></section>
<section class="panel"><h2>Hinweis</h2><div class="muted">Dieser Exporter ist ein separates Zusatzprogramm. Er gehört nicht in die CurseForge-Addon-ZIP. Sobald dein endgültiger Download-Link feststeht, kann er später im Addon und in der CurseForge-Beschreibung ergänzt werden.</div><div class="actions"><button class="danger" onclick="quitApp()">Exporter beenden</button></div></section><div class="footer">Azeroth Diary Exporter</div></main><script>
let loaded=false, editing=false;const $=id=>document.getElementById(id);['source','output','language','wowhead','auto','openAfter'].forEach(id=>$(id).addEventListener('change',saveConfig));$('source').addEventListener('input',()=>editing=true);$('output').addEventListener('input',()=>editing=true);$('sourceList').addEventListener('change',()=>{if($('sourceList').value){$('source').value=$('sourceList').value;saveConfig()}});
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw new Error(j.error||'Fehler');return j}
function cfg(){return{source:$('source').value,output:$('output').value,language:$('language').value,wowhead:$('wowhead').checked,auto:$('auto').checked,openAfter:$('openAfter').checked}}
async function saveConfig(){try{await api('/api/config',cfg());editing=false}catch(e){showError(e.message)}}
function fillSources(items,current){const list=$('sourceList'),old=list.value;list.textContent='';const p=document.createElement('option');p.value='';p.textContent=items.length?'Gefundene Datei auswählen…':'Keine Datei automatisch gefunden';list.appendChild(p);for(const item of items){const o=document.createElement('option');o.value=item.path;o.textContent=item.label;list.appendChild(o)}const value=current||old;if([...list.options].some(o=>o.value===value))list.value=value}
function showStatus(title,text,ok=true){const s=$('status');s.className='status '+(ok?'ok':'err');s.innerHTML='<b></b><span></span>';s.querySelector('b').textContent=title;s.querySelector('span').textContent=text}
function showError(text){showStatus('Fehler',text,false)}
async function loadState(){try{const s=await api('/api/state');$('version').textContent='v'+s.version;fillSources(s.sources,s.config.source);if(!editing||!loaded){$('source').value=s.config.source||'';$('output').value=s.config.output||'';$('language').value=s.config.language||'de';$('wowhead').checked=!!s.config.wowhead;$('auto').checked=!!s.config.auto;$('openAfter').checked=!!s.config.openAfter}if(s.status.message)showStatus(s.status.title||'Status',s.status.message,s.status.ok!==false);loaded=true}catch(e){showError(e.message)}}
async function refreshSources(){try{const s=await api('/api/refresh',{});fillSources(s.sources,$('source').value);showStatus('Suche abgeschlossen',s.sources.length+' SavedVariables-Datei(en) gefunden.')}catch(e){showError(e.message)}}
async function runExport(){try{await saveConfig();const r=await api('/api/export',{});showStatus('Export fertig',r.entries+' Erinnerungen wurden in die HTML geschrieben.')}catch(e){showError(e.message)}}
async function openOutput(){try{await api('/api/open-output',{})}catch(e){showError(e.message)}}async function openFolder(){try{await api('/api/open-folder',{})}catch(e){showError(e.message)}}
async function pickSource(){try{const r=await api('/api/pick-source',{});if(r.path){$('source').value=r.path;await saveConfig();await loadState()}}catch(e){showError(e.message)}}async function pickOutput(){try{const r=await api('/api/pick-output',{});if(r.path){$('output').value=r.path;await saveConfig()}}catch(e){showError(e.message)}}
async function quitApp(){try{await api('/api/quit',{})}catch(e){}document.body.innerHTML='<main class="wrap"><section class="hero"><h1>Exporter beendet</h1><div class="muted">Dieses Browserfenster kann geschlossen werden.</div></section></main>'}
const liveConnection=new EventSource('/api/live');liveConnection.onerror=()=>{};loadState();setInterval(()=>{if(!editing)loadState()},2500);
</script></body></html>`
